package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.ContentReader;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactoryImpl;
import com.fasterxml.jackson.core.io.JsonParserImpl;
import com.fasterxml.jackson.core.io.SerializableString;
import com.fasterxml.jackson.core.io.SerializableStringImpl;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser#nextFieldName
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen2Test {

    private JsonFactory factory;

    @Before
    public void setUp() {
        factory = new JsonFactoryImpl();
    }

    private JsonParser createParser(String json) throws IOException {
        return factory.createParser(new StringReader(json));
    }

    @Test
    public void testNextFieldName_MatchLiteral() throws IOException {
        // Tests the fast path: matching sstr against input buffer directly
        String json = "{\"name\":\"value\"}";
        JsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT

        SerializableString target = new SerializableStringImpl("name");
        boolean found = parser.nextFieldName(target);

        assertTrue("Should return true when field name matches", found);
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals("value", parser.getText());
    }

    @Test
    public void testNextFieldName_NoMatch() throws IOException {
        String json = "{\"age\":30}";
        JsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT

        SerializableString target = new SerializableStringImpl("name");
        boolean found = parser.nextFieldName(target);

        assertFalse("Should return false when field name does not match", found);
    }

    @Test
    public void testNextFieldName_AfterFieldName() throws IOException {
        // Tests the logic: if (_currToken == JsonToken.FIELD_NAME) { _nextAfterName(); return false; }
        String json = "{\"name\":\"value\"}";
        JsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME ("name")

        SerializableString target = new SerializableStringImpl("name");
        // Calling nextFieldName while current token is FIELD_NAME
        boolean found = parser.nextFieldName(target);

        assertFalse("Should return false when current token is already FIELD_NAME", found);
        assertEquals(JsonToken.VALUE_STRING, parser.getCurrentToken());
    }

    @Test
    public void testNextFieldName_EndArrayInObject() throws IOException {
        // Tests the branch where i == INT_RBRACKET (mismatched end marker)
        // Note: The code reports mismatched end marker if inArray() is false but we see ']'
        // To trigger the error, we need to be in an object context and see ']'
        String json = "{\"key\": [] }"; 
        // This is tricky because the parser context manages state. 
        // Let's simulate a malformed JSON sequence.
        String malformed = "{\"key\": ]"; 
        JsonParser parser = createParser(malformed);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME
        parser.nextToken(); // This will trigger error when trying to parse value or next field

        try {
            parser.nextFieldName(new SerializableStringImpl("key"));
            fail("Should have thrown IOException due to mismatched end marker");
        } catch (IOException e) {
            // Expected
        }
    }

    @Test
    public void testNextFieldName_EndObjectInObject() throws IOException {
        // Tests the logic for i == INT_RCURLY
        String json = "{\"a\": {}}";
        JsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "a"
        parser.nextToken(); // START_OBJECT (nested)

        // Now we are inside nested object. 
        // If we find '}', it should return false and set token to END_OBJECT
        parser.nextFieldName(new SerializableStringImpl("a")); // dummy to move past name
        parser.nextToken(); // END_OBJECT

        // Attempting to find next field name after END_OBJECT
        // This tests the context parent logic
    }

    @Test
    public void testNextFieldName_IncompleteToken() throws IOException {
        // Tests the _tokenIncomplete branch
        // This usually happens in streaming scenarios with partial buffers
        String json = "{\"name\" : \"value\"}";
        JsonParser parser = createParser(json);
        parser.nextToken();

        // Manually triggering a state that might lead to incomplete token is hard via StringReader
        // but we can test the standard flow which covers skipWSOrEnd
        SerializableString target = new SerializableStringImpl("name");
        assertTrue(parser.nextFieldName(target));
    }

    @Test
    public void testNextFieldName_EndOfInput() throws IOException {
        String json = "{}";
        JsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT

        // Next field name after the object is empty
        // The parser should see '}' and return false
        SerializableString target = new SerializableStringImpl("any");
        boolean result = parser.nextFieldName(target);

        assertFalse(result);
        assertEquals(JsonToken.END_OBJECT, parser.getCurrentToken());
    }

    @Test
    public void testNextFieldName_NotInsideObject() throws IOException {
        // Tests if (!_parsingContext.inObject()) { _nextTokenNotInObject(i); return false; }
        String json = "[1, 2, 3]";
        JsonParser parser = createParser(json);

        parser.nextToken(); // START_ARRAY

        SerializableString target = new SerializableStringImpl("name");
        // We are in an array, calling nextFieldName should fail
        boolean result = parser.nextFieldName(target);

        assertFalse(result);
    }

    @Test
    public void testNextFieldName_SkipComma() throws IOException {
        // Tests the _parsingContext.expectComma() branch
        String json = "{\"a\":1, \"b\":2}";
        JsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT
        parser.nextFieldName(new SerializableStringImpl("a"));
        parser.nextToken(); // VALUE_1

        // After value 1, we expect a comma if we want to find the next field
        SerializableString target = new SerializableStringImpl("b");
        boolean found = parser.nextFieldName(target);

        assertTrue("Should skip comma and find 'b'", found);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
    }

    @Test
    public void testNextFieldName_LiteralMatchWithColonFastPath() throws IOException {
        // Specifically tests the 'if (i == INT_QUOTE)' block with the fast colon skip
        String json = "{\"test\":true}";
        JsonParser parser = createParser(json);

        parser.nextToken(); // START_OBJECT

        SerializableString target = new SerializableStringImpl("test");
        boolean found = parser.nextFieldName(target);

        assertTrue(found);
        assertEquals(JsonToken.VALUE_TRUE, parser.nextToken());
    }
}
